// The silhouette the block samples, inlined as a data URI.
//
// A shadcn registry item carries text files only, so a .jpeg beside the
// component would not survive `npx shadcn add` — the image has to travel as
// source. Downscaled to 660px wide (the canvas draws it at ~324x392 CSS px at
// the widest breakpoint, so this is still 2x) to keep the registry JSON sane.
export const PORTRAIT_SRC =
  "data:image/jpeg;base64,";
